window.ScripturaLexicons.BDAG_PART_0161 = {"source":"BDAG","searchAnchorId":"bdag-search-anchor","entryAnchorId":"bdag-entry-anchor","rowsHtml":"<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-edypatheia-bdag\" data-source=\"BDAG\" data-search=\"ἡδυπάθεια, ας, ἡ substantivo feminino vida luxuosa; prazer; conforto BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἡδυπάθεια, ας, ἡ</td><td>substantivo feminino</td><td>vida luxuosa; prazer; conforto</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-edys-bdag\" data-source=\"BDAG\" data-search=\"ἡδύς, εῖα, ύ adjetivo agradável; aprazível BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἡδύς, εῖα, ύ</td><td>adjetivo</td><td>agradável; aprazível</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-ethos-bdag\" data-source=\"BDAG\" data-search=\"ἦθος, ους, τό substantivo neutro costume; hábito; maneira de proceder BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἦθος, ους, τό</td><td>substantivo neutro</td><td>costume; hábito; maneira de proceder</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-heko-bdag\" data-source=\"BDAG\" data-search=\"ἥκω verbo ter chegado; estar presente; ocorrer BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἥκω</td><td>verbo</td><td>ter chegado; estar presente; ocorrer</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-elamen-bdag\" data-source=\"BDAG\" data-search=\"ἡλάμην forma verbal remissiva ver ἅλλομαι BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἡλάμην</td><td>forma verbal remissiva</td><td>ver ἅλλομαι</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-elenchthen-bdag\" data-source=\"BDAG\" data-search=\"ἠλέγχθην forma verbal remissiva ver ἐλέγχω BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἠλέγχθην</td><td>forma verbal remissiva</td><td>ver ἐλέγχω</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-eltha-elthon-bdag\" data-source=\"BDAG\" data-search=\"ἦλθα, ἦλθον formas verbais remissivas ver ἔρχομαι BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἦλθα, ἦλθον</td><td>formas verbais remissivas</td><td>ver ἔρχομαι</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-eli-aram-bdag\" data-source=\"BDAG\" data-search=\"ἠλί transliteração de expressão hebraica meu Deus BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἠλί</td><td>transliteração de expressão hebraica</td><td>meu Deus</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-eli-person-bdag\" data-source=\"BDAG\" data-search=\"Ἠλί, ὁ nome próprio masculino Eli; Heli BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Ἠλί, ὁ</td><td>nome próprio masculino</td><td>Eli; Heli</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-elias-bdag\" data-source=\"BDAG\" data-search=\"Ἠλίας, ου, ὁ nome próprio masculino Elias; profeta Elias BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Ἠλίας, ου, ὁ</td><td>nome próprio masculino</td><td>Elias; profeta Elias</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-elikia-bdag\" data-source=\"BDAG\" data-search=\"ἡλικία, ας, ἡ substantivo feminino idade; maturidade; estatura BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἡλικία, ας, ἡ</td><td>substantivo feminino</td><td>idade; maturidade; estatura</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-elikos-bdag\" data-source=\"BDAG\" data-search=\"ἡλίκος, η, ον adjetivo quão grande; quão pequeno BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἡλίκος, η, ον</td><td>adjetivo</td><td>quão grande; quão pequeno</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-elios-bdag\" data-source=\"BDAG\" data-search=\"ἥλιος, ου, ὁ substantivo masculino sol BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἥλιος, ου, ὁ</td><td>substantivo masculino</td><td>sol</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-elioupolis-bdag\" data-source=\"BDAG\" data-search=\"Ἡλιούπολις, εως, ἡ nome próprio feminino Heliópolis BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Ἡλιούπολις, εως, ἡ</td><td>nome próprio feminino</td><td>Heliópolis</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-elos-bdag\" data-source=\"BDAG\" data-search=\"ἧλος, ου, ὁ substantivo masculino prego; cravo BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἧλος, ου, ὁ</td><td>substantivo masculino</td><td>prego; cravo</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-elysion-pedion-bdag\" data-source=\"BDAG\" data-search=\"Ἠλύσιον πεδίον, τό expressão nominal neutra Campos Elísios; Elísio BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Ἠλύσιον πεδίον, τό</td><td>expressão nominal neutra</td><td>Campos Elísios; Elísio</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-emeis-bdag\" data-source=\"BDAG\" data-search=\"ἡμεῖς pronome pessoal remissivo nós; ver ἐγώ BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἡμεῖς</td><td>pronome pessoal remissivo</td><td>nós; ver ἐγώ</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-emera-bdag\" data-source=\"BDAG\" data-search=\"ἡμέρα, ας, ἡ substantivo feminino dia; período diurno; data determinada; época BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἡμέρα, ας, ἡ</td><td>substantivo feminino</td><td>dia; período diurno; data determinada; época</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-emeros-bdag\" data-source=\"BDAG\" data-search=\"ἥμερος, ον adjetivo manso; brando; bondoso BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἥμερος, ον</td><td>adjetivo</td><td>manso; brando; bondoso</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-emeroo-bdag\" data-source=\"BDAG\" data-search=\"ἡμερόω verbo domesticar; amansar; refrear BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἡμερόω</td><td>verbo</td><td>domesticar; amansar; refrear</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n","cardsHtml":"<article id=\"entry-edypatheia-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἡδυπάθεια, ας, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">(<span class=\"greek\">ἡδύς</span> + <span class=\"greek\">πάθη</span>, «experiência de algo agradável»; Xenofonte, Cyr. 7, 5, 74; Cebes 9, 3; 28, 1; Plutarco, Mor. 132c; 4Mc 2:2, 4). <strong>Experiência de vida luxuosa, desfrute, conforto</strong>; no plural (Ateneu 4, 165e): <span class=\"greek\">ἀποτάσσεσθαι</span> <span class=\"greek\">ταῖς</span> <span class=\"greek\">ἡδ</span>., «renunciar aos prazeres», 2Cl 16:2; <span class=\"greek\">μισεῖν</span> <span class=\"greek\">τὰς</span> <span class=\"greek\">ἡδ</span>. <span class=\"greek\">τῆς</span> <span class=\"greek\">ψυχῆς</span>, «odiar os prazeres malignos da alma», 2Cl 17:7. Cf. DELG, s.v. <span class=\"greek\">ἥδομαι</span> B.</p></section></article>\n<article id=\"entry-edys-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἡδύς, εῖα, ύ</h1><div class=\"entry-meta\"><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">(Cf. <span class=\"greek\">ἥδομαι</span>; Homero e outros; inscrições, papiros, LXX, En, ParJer 5:3; EpArist, Fílon; Josefo, Ant. 12, 47, <span class=\"greek\">ἡδὺ</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">θεῷ</span>; Atanásio 33, 1 [substantivado no plural]). Originalmente referido a algo agradável aos sentidos; depois, a tudo aquilo que agrada ou é bem-vindo: <strong>agradável, aprazível</strong>. <span class=\"greek\">αὕτη</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">ὁδὸς</span> <span class=\"greek\">ἡδυτέρα</span> <span class=\"greek\">αὐτοῖς</span> <span class=\"greek\">ἐγένετο</span>, «esse caminho tornou-se mais adequado a eles», Hs 8, 9, 1 (Pseudo-Dicearco, p. 140 F., <span class=\"greek\">ὁδὸς</span> <span class=\"greek\">ἡδεῖα</span>). — B. 1032; DELG, s.v. <span class=\"greek\">ἥδομαι</span> B; Spicq; Sv.</p></section></article>\n<article id=\"entry-ethos-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἦθος, ους, τό</h1><div class=\"entry-meta\"><span>substantivo neutro</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">(Homero e outros.) <strong>Padrão de comportamento ou prática habitual característico de um grupo ou pessoa: costume, uso, hábito</strong> (Hesíodo, Heródoto e outros). <span class=\"greek\">τῆς</span> <span class=\"greek\">ἁγνείας</span>, «hábito da pureza», 1Cl 21:7; <span class=\"greek\">τῆς</span> <span class=\"greek\">φιλοξενίας</span>, «[hábito] da hospitalidade», 1Cl 1:2. Plural <span class=\"greek\">τὰ</span> <span class=\"greek\">ἤθη</span>, «hábitos», <span class=\"greek\">ἤθη</span> <span class=\"greek\">χρηστά</span>, «bons hábitos» (cf. Fílon, Spec. Leg. 2, 104; EpArist 290; POxy 642 [século II d.C.], <span class=\"greek\">ἦθος</span> <span class=\"greek\">χρηστόν</span>), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.15.33\" target=\"_blank\" rel=\"noopener noreferrer\">1Co 15:33</a>. O dito <span class=\"greek\">φθείρουσιν</span> <span class=\"greek\">ἤθη</span> <span class=\"greek\">χρηστὰ</span> <span class=\"greek\">ὁμιλίαι</span> <span class=\"greek\">κακαί</span>, «más companhias corrompem bons costumes», é provérbio encontrado na comédia <em>Tais</em> de Menandro (Fgm. 218 Kock; 187 Körte) e talvez já em Eurípides (PHib 7, 94 [século III a.C.]; Sócrates, HE 3, 6). Sobre a atribuição e a transmissão, ver a discussão da fonte; cf. ainda DELG; M-M; TW.</p></section><p class=\"entry-text\">Em Diodoro Sículo 12, 12, [3] 4, o legislador Carondas (século V a.C.) defende que os bons podem facilmente perder o caráter pelo convívio com maus: <span class=\"greek\">τὰ</span> <span class=\"greek\">ἤθη</span> <span class=\"greek\">πρὸς</span> <span class=\"greek\">κακίαν</span>. Em 16, 54, 4, diz-se de um tirano: <span class=\"greek\">πονηραῖς</span> <span class=\"greek\">ὁμιλίαις</span> <span class=\"greek\">διέφθειρε</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">ἤθη</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">ἀνθρώπων</span>, «corrompeu os costumes das pessoas por conversas vis». Ver <span class=\"greek\">χρηστός</span> 3a; ideias semelhantes já em Teógnis 1, 35s.; 305–8. Com relação às leis judaicas, aparece como variante de leitura em At 16:21 e 26:3 (ver <span class=\"greek\">ἔθος</span> 2). As formas abreviadas <span class=\"greek\">τὰ</span> <span class=\"greek\">ἤθη</span>, <span class=\"greek\">ἤθ</span>. <span class=\"greek\">χρ</span>. conservam a flexão da fonte.</p></article>\n<article id=\"entry-heko-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἥκω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">(Homero e outros; inscrições, papiros, LXX, pseudepígrafos; Josefo, Ant. 16, 329, 341 e outros; Justino, A II, 2, 5; no lugar de <span class=\"greek\">ἔρχεσθαι</span>, Justino, D. 49, 3; 88, 7 [<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.3.11\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 3:11s</a>.]; D. 53, 3 [Zc 9:9]; no lugar de <span class=\"greek\">ἤχθη</span>, Justino, A I, 51, 1; D. 13, 6 [Is 53:8]). Por possuir valor de perfeito, sua conjugação às vezes inclui formas perfeitas (papiros [Mayser I²/2, 1938, 148]; LXX [Helbing 104]; JosAs 3:7s.; Josefo [W. Schmidt 470]): <span class=\"greek\">ἥκασι</span>(<span class=\"greek\">ν</span>), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.8.3\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 8:3</a> (variante <span class=\"greek\">ἥκουσιν</span>); 1Cl 12:2. Imperfeito <span class=\"greek\">ἧκον</span>; futuro <span class=\"greek\">ἥξω</span>; primeiro aoristo <span class=\"greek\">ἧξα</span> (POxy 933, 13).</p><p class=\"entry-text\">① <strong>Estar em determinado lugar como resultado de movimento; ter chegado, estar presente</strong>, de pessoas.</p><p class=\"entry-text\">ⓐ Com referência ao ponto de partida: <span class=\"greek\">ἀπό</span> <span class=\"greek\">τινος</span>, «de algum lugar», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.8.11\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 8:11</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.13.29\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 13:29</a>; <span class=\"greek\">ἔκ</span> <span class=\"greek\">τινος</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.4.47\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 4:47</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.11.26\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 11:26</a>; <span class=\"greek\">μακρόθεν</span>, «de longe», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.8.3\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 8:3</a> (cf. Js 9:6, 9; Is 60:4; F. Danker, JBL 82, 1963, 215s.).</p><p class=\"entry-text\">ⓑ Com menção ao destino: <span class=\"greek\">εἴς</span> <span class=\"greek\">τι</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.4.47\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 4:47</a> (ver a acima); <span class=\"greek\">ἥ</span>. <span class=\"greek\">εἰς</span> <span class=\"greek\">θάνατον</span>, «ir para a morte», 1Cl 16:9; <span class=\"greek\">ἥ</span>. <span class=\"greek\">εἰς</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">πύρωσιν</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">δοκιμασίας</span>, «chegar à prova de fogo», D 16:5; <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">οἴκῳ</span> <span class=\"greek\">αὐτοῦ</span>, «em sua casa», GJs 5:1; <span class=\"greek\">πρός</span> <span class=\"greek\">τινα</span>, «a alguém» (PSI 326, 4 [261 a.C.]; En 106:8), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.28.23\" target=\"_blank\" rel=\"noopener noreferrer\">At 28:23</a>, variante de leitura; GJs 9:3; <span class=\"greek\">ἐπί</span> <span class=\"greek\">τινα</span>, «chegar a alguém» (UPZ 78, 44 [159 a.C.]), também com intenção hostil (Platão, Rep. 336b; 2Cr 20:2), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.3.3\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 3:3b</a>; <span class=\"greek\">ἐπί</span> <span class=\"greek\">τι</span> (Luciano, Jupp. Tr. 24; Aquiles Tácio 5, 10, 1), B 4:3. Seguido de infinitivo, 1Cl 12:2; <span class=\"greek\">ἕως</span> <span class=\"greek\">ὧδε</span>, «até aqui», 1Cl 20:7; <span class=\"greek\">ἐκεῖ</span>, «lá» (POslo 58, 5), Hv 3, 1, 3.</p><p class=\"entry-text\">ⓒ Em emprego absoluto, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.24.50\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 24:50</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.12.46\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 12:46</a>; 15:27; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.8.42\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 8:42</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.10.7\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 10:7</a>, 9 (ambos Sl 39:8), 37 (Hc 2:3); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1JN.5.20\" target=\"_blank\" rel=\"noopener noreferrer\">1Jo 5:20</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.2.25\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 2:25</a>; 3:3a, 9; 1Cl 23:5 (Ml 3:1); D 16:7. <span class=\"greek\">ἰδοὺ</span> <span class=\"greek\">ἥκει</span> <span class=\"greek\">Ἰωακεὶμ</span> <span class=\"greek\">μετὰ</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">ποιμνίων</span> <span class=\"greek\">αὐτοῦ</span>, «eis que Joaquim chegou com seus rebanhos», GJs 4:4.</p><p class=\"entry-text\">ⓓ Da chegada de adorador a uma divindade (OGI 186, 6, <span class=\"greek\">ἥκω</span> <span class=\"greek\">πρὸς</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">κυρίαν</span> <span class=\"greek\">῏Ισιν</span>; 196, 2; Sb 1059, 8402 [século I a.C.], 8411 [79 a.C.], 8412 [66 a.C.] e outros; 3Km 8:42; Jr 27:5; <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">σὲ</span> <span class=\"greek\">ἥξομεν</span>, PsSol 5:7), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.6.37\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 6:37</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.15.4\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 15:4</a> (Sl 85:9).</p><p class=\"entry-text\">ⓔ De aparição solene: <strong>estar aqui, apresentar-se</strong> (de divindade, PGM 1, 26, 29; Zósimo, Herm. Wr. IV, p. 111, 5, <span class=\"greek\">θεὸς</span> <span class=\"greek\">ἥξει</span> <span class=\"greek\">πρός</span> <span class=\"greek\">σε</span>; 111, 9; Sinésio, Provid. 2, 2, p. 118b; SibOr 3, 49); expresso enfaticamente por <span class=\"greek\">ἥκω</span> (PGiss 3, 2 [ver <span class=\"greek\">ἄγνωστος</span>]; O. Weinreich, ARW 18, 1915, 38ss.), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.8.42\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 8:42</a>.</p><p class=\"entry-text\">② <strong>Aparecer ou acontecer, sobrevir</strong>, em emprego impessoal (Demóstenes 23, 12; Diodoro Sículo 18, 58, 2, <span class=\"greek\">ἧκε</span> <span class=\"greek\">γράμματα</span>, «chegou uma carta»; Plutarco, Philop. 366 [21, 1]; Epicteto 2, 2, 20; Élio Aristides 48, 13 K. = 24, p. 468 D.). Sobre tempo (Ez 7:12, <span class=\"greek\">ἥκει</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">καιρός</span>; Sl 101:14) ou acontecimentos, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.24.14\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 24:14</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.2.4\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 2:4</a>; 13:1, variante de leitura; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2PE.3.10\" target=\"_blank\" rel=\"noopener noreferrer\">2Pe 3:10</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.18.8\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 18:8</a>. De informações ou relatos, <span class=\"greek\">ὡς</span> <span class=\"greek\">ἐκ</span> <span class=\"greek\">παραδόσεως</span> <span class=\"greek\">ἀγράφου</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">αὐτὸν</span> <span class=\"greek\">ἥκοντα</span>, «como vindos até ele de tradição não escrita», Pápias 2:11. Do Reino de Deus, 2Cl 12:2. <span class=\"greek\">ἕως</span> <span class=\"greek\">ἥξει</span> <span class=\"greek\">ὅτε</span>, «até que chegue o tempo em que», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.13.35\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 13:35</a>. <span class=\"greek\">ἐπί</span> <span class=\"greek\">τινα</span>, «sobre alguém» (Is 47:9; cf. <span class=\"greek\">τὰ</span> <span class=\"greek\">ἀγαθὰ</span> <span class=\"greek\">ἥξε</span>...), ver complemento abaixo. — DELG; M-M; TW.</p></section><p class=\"entry-text\">Complemento de ②: <span class=\"greek\">ἐπί</span> <span class=\"greek\">τινα</span>, «sobre alguém» (Is 47:9; cf. <span class=\"greek\">τὰ</span> <span class=\"greek\">ἀγαθὰ</span> <span class=\"greek\">ἥξεις</span> … <span class=\"greek\">ἐπ</span>’ <span class=\"greek\">αὐτούς</span>, En 107:1), das tribulações finais, Mt 23:36; Lc 19:43. A forma verbal e seu emprego são citados no trecho original; DELG; M-M; TW.</p></article>\n<article id=\"entry-elamen-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἡλάμην</h1><div class=\"entry-meta\"><span>forma verbal remissiva</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">Ver <span class=\"greek\">ἅλλομαι</span>.</p></section></article>\n<article id=\"entry-elenchthen-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἠλέγχθην</h1><div class=\"entry-meta\"><span>forma verbal remissiva</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">Ver <span class=\"greek\">ἐλέγχω</span>.</p></section></article>\n<article id=\"entry-eltha-elthon-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἦλθα, ἦλθον</h1><div class=\"entry-meta\"><span>formas verbais remissivas</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">Ver <span class=\"greek\">ἔρχομαι</span>.</p></section></article>\n<article id=\"entry-eli-aram-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἠλί</h1><div class=\"entry-meta\"><span>transliteração de expressão hebraica</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">(Variante <span class=\"greek\">ἐλωί</span>; outras grafias: <span class=\"greek\">ἡλι</span>, <span class=\"greek\">ἡλει</span>, <span class=\"greek\">ἠλει</span>.) Equivale ao hebraico אֵלִי, <strong>«meu Deus»</strong> (Sl 22:2 hebraico), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.27.46\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 27:46</a>. — G. Dalman, <em>Jesus-Jeshua</em>, 1929 [trad. P. Levertoff], 204–7; F. Buckler, AJSL 55, 1938, 378–91; W. Kenneally, CBQ 8, 1946, 124–34; F. Zimmerman, JBL 66, 1947, 465s.</p></section></article>\n<article id=\"entry-eli-person-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Ἠλί, ὁ</h1><div class=\"entry-meta\"><span>nome próprio masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">(Edições também <span class=\"greek\">Ἡλί</span>, <span class=\"greek\">Ἡλεί</span>; hebraico עֵלִי; cf. 1Km 1:3; 2:12, 20, 22; 3Km 2:27. Em Josefo, Ant. 5, 340s. e outros, <span class=\"greek\">Ἠλ</span>[<span class=\"greek\">ε</span>]<span class=\"greek\">ίς</span>; genitivo <span class=\"greek\">Ἠλεῖ</span>, 5, 341, 350.) <strong>Eli (Heli)</strong>, pai (ou, segundo alguns, avô) de José, na genealogia de Jesus, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.3.23\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 3:23</a>. — M-M, s.v. <span class=\"greek\">Ἠλεί</span>.</p></section></article>\n<article id=\"entry-elias-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Ἠλίας, ου, ὁ</h1><div class=\"entry-meta\"><span>nome próprio masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">(Edições também -<span class=\"greek\">είας</span>, <span class=\"greek\">Ἡλείας</span>, <span class=\"greek\">Ἡλίας</span>; hebraico אֵלִיָּה ou אֵלִיָּהוּ.) <strong>Elias</strong>, o tisbita, profeta (3Km 17–20; 4Km 1s.; 2Cr 21:12; Ml 3:22; Eclo 48:1, 4, 12; ApcEl [PSI 7 verso, 4]; AscIs 2:14; SibOr 2, 247; Josefo, ApcEsdr, Justino), cuja vida e feitos foram considerados de grande importância pelos compatriotas de Jesus (Schürer II 515s., 604s.; Billerb. IV 764–98), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.11.14\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 11:14</a>; 16:14; 17:3s. (P. Dabeck, Biblica 23, 1942, 175–89), 10ss.; 27:47, 49; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.6.15\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 6:15</a>; 8:28; 9:4s., 11ss.; 15:35s.; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.17\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 1:17</a>; 4:25s.; 9:8, 19, 30, 33, 54, variante de leitura; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.1.21\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 1:21</a>, 25; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.5.17\" target=\"_blank\" rel=\"noopener noreferrer\">Tg 5:17</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.11.2\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 11:2</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.11.6\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 11:6</a> (alusão); cf. 1Cl 17:1; 2Cl 9:7. — </p></section><p class=\"entry-text\">Na expressão <span class=\"greek\">ἐν</span> <span class=\"greek\">Ἠλίᾳ</span>, «na narrativa de Elias», Rm 11:2. — J. Robinson, *Elijah, John and Jesus: 12 NT Studies*, 1962, 28–52; G. Fohrer, *Elia*, 1968²; EDNT; TW.</p></article>\n<article id=\"entry-elikia-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἡλικία, ας, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">(Homero e autores posteriores.)</p><p class=\"entry-text\">① <strong>Período de duração da vida de uma pessoa: idade, tempo de vida</strong>.</p><p class=\"entry-text\">ⓐ De maneira geral, tempo já transcorrido. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.6.27\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 6:27</a> = <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.12.25\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 12:25</a>, <span class=\"greek\">προσθεῖναι</span> <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">τ</span>. <span class=\"greek\">ἡλικίαν</span> <span class=\"greek\">αὐτοῦ</span> <span class=\"greek\">πῆχυν</span> <span class=\"greek\">ἕνα</span>, «acrescentar um côvado à própria idade», em que, segundo o contexto, a referência é a algo insignificante (<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.12.26\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 12:26</a> usa expressamente <span class=\"greek\">ἐλάχιστον</span>; Pausânias Ático, <span class=\"greek\">ς</span>, 22, avalia como <span class=\"greek\">τὸ</span> <span class=\"greek\">ἐλάχιστον</span> a expressão <span class=\"greek\">σπιθαμὴ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">βίου</span>, «um palmo de vida»). Pode referir-se à duração da vida (Goodsp., <em>Problems</em>, 24–26, seguindo Wetstein), não ao tamanho do corpo; <span class=\"greek\">πῆχυς</span> seria, então, medida de tempo (cf. Sl 39:6 hebraico; ver <span class=\"greek\">πῆχυς</span>). Talvez igualmente na passagem paralela Ox 655, 13–15 (GTh 67, 34; Fitzmyer 544).</p><p class=\"entry-text\">ⓑ Da idade em geral, inclusive os anos ainda por vir: <span class=\"greek\">προκόπτειν</span> <span class=\"greek\">ἐν</span> (omitido em muitos manuscritos) <span class=\"greek\">τ</span>. <span class=\"greek\">ἡλικίᾳ</span>, «avançar em idade», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.2.52\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 2:52</a> (mas ver ③ abaixo; cf. SIG 708, 17–19: inscrição honorífica de um jovem de Istrópolis [século II a.C.], [<span class=\"greek\">τῇ</span>] <span class=\"greek\">τε</span> <span class=\"greek\">ἡλικίᾳ</span> <span class=\"greek\">προκόπτων</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">προαγόμενος</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">θεοσεβεῖν</span> <span class=\"greek\">ὡς</span> <span class=\"greek\">ἔπρεπεν</span> <span class=\"greek\">αὐτῷ</span> <span class=\"greek\">πρῶτον</span> <span class=\"greek\">μὲν</span> <span class=\"greek\">ἐτείμησεν</span> <span class=\"greek\">τοὺς</span> <span class=\"greek\">θεοὺς</span>, «avançando em anos e crescendo na piedade, como lhe convinha, primeiro honrou os deuses»; <em>Biogr.</em>, p. 266; sobre <span class=\"greek\">σοφία</span>, <span class=\"greek\">ἡλικία</span>, <span class=\"greek\">χάρις</span>, A. Fridrichsen, SymbOsl 6, 1928, 33–38).</p><p class=\"entry-text\">② <strong>Idade suficiente ou necessária para determinadas coisas; maturidade</strong> (Josefo, Ant. 1, 68; 2, 230a).</p><p class=\"entry-text\">ⓐ Idade de pleno vigor (2Mc 5:24; 7:27; En 106:1), também de mulheres (<span class=\"greek\">αἱ</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">ἡλ</span>. <span class=\"greek\">παρθένοι</span> ou <span class=\"greek\">γυναῖκες</span>, em Hipócrates, Platão, Plutarco). <span class=\"greek\">παρὰ</span> <span class=\"greek\">καιρὸν</span> <span class=\"greek\">ἡλικίας</span>, «além da idade habitual», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.11.11\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 11:11</a> (ver <span class=\"greek\">καταβολή</span> 1 e 2; Fílon, Abr. 195). Figuradamente, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.4.13\" target=\"_blank\" rel=\"noopener noreferrer\">Ef 4:13</a>: <span class=\"greek\">εἰς</span> <span class=\"greek\">ἄνδρα</span> <span class=\"greek\">τέλειον</span>, <span class=\"greek\">εἰς</span> <span class=\"greek\">μέτρον</span> <span class=\"greek\">ἡλικίας</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">πληρώματος</span> <span class=\"greek\">τ</span>. <span class=\"greek\">Χριστοῦ</span>, «até a medida da plena maturidade de Cristo, que é pessoa adulta» (<span class=\"greek\">τέλειος</span>), não menor (<span class=\"greek\">νήπιος</span>; cf. Diodoro Sículo 18, 57, 2, <span class=\"greek\">εἰς</span> <span class=\"greek\">ἡλικίαν</span> <span class=\"greek\">ἔρχεσθαι</span>); mas ver ③.</p><p class=\"entry-text\">ⓑ <strong>Maioridade jurídica</strong> (frequente em papiros): <span class=\"greek\">ἡλικίαν</span> <span class=\"greek\">ἔχειν</span>, «ser maior de idade» (Platão, Euthd. 306d; Plutarco, Mor. 547a; BGU 168, 5, <span class=\"greek\">τοῖς</span> <span class=\"greek\">ἀτελέσι</span> <span class=\"greek\">ἔχουσι</span> <span class=\"greek\">τ</span>. <span class=\"greek\">ἡλικίαν</span>), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.9.21\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 9:21</a>, 23.</p><p class=\"entry-text\">③ <strong>Estatura corporal</strong> (Heródoto 3, 16; Platão, Euthd. 271b; Demóstenes 40, 56; Diodoro Sículo 3, 35, 6; Plutarco, Philop. 362 [11, 2]; Luciano, Ver. Hist. 1, 40; Josefo, Ant. 2, 230b). <span class=\"greek\">τῇ</span> <span class=\"greek\">ἡλικίᾳ</span> <span class=\"greek\">μικρὸς</span> <span class=\"greek\">ἦν</span>, «era pequeno de estatura», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.19.3\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 19:3</a>. Alguns estudiosos incluem aqui <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.6.27\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 6:27</a> e <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.12.25\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 12:25</a> (Field, <em>Notes</em>, 6s.); muitos preferem «estatura» para <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.2.52\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 2:52</a> e <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.4.13\" target=\"_blank\" rel=\"noopener noreferrer\">Ef 4:13</a>. — B. 956; DELG, s.v. <span class=\"greek\">ἧλιξ</span>; M-M; TW; Sv.</p></section><p class=\"entry-text\">Complemento de ①ⓐ: a passagem paralela Ox 655, 13–15 (GTh 67, 34; Fitzmyer 544) apresenta <span class=\"greek\">τίς</span> <span class=\"greek\">ἄν</span> <span class=\"greek\">προσθ</span>‹<span class=\"greek\">εί</span>›<span class=\"greek\">η</span>| <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">εἱλικίαν</span>| <span class=\"greek\">ὑμῶν</span>;, «quem poderia acrescentar à duração da vossa vida?». Em contrapartida, como o contexto trata também de alimentação e crescimento, pode representar uma expressão enfática de Jesus acerca da estatura: «quem cresce preocupando-se com a própria altura?» (ver ③). Conforme o contexto, <span class=\"greek\">ἡλ</span>. pode denotar mais especificamente juventude (4Mc 8:10, 20; IMg 3:1; MPol 3:1) ou velhice (MPol 7:2; 9:2; cf. 4Mc 5:6, 11, 36). Ainda em Ef 4:13, a oposição explícita <span class=\"greek\">ἵνα</span> <span class=\"greek\">μηκέτι</span> <span class=\"greek\">ὦμεν</span> <span class=\"greek\">νήπιοι</span>, «para que não sejamos mais menores», fundamenta o sentido de maturidade; cf. <span class=\"greek\">παρά</span> C3.</p></article>\n<article id=\"entry-elikos-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἡλίκος, η, ον</h1><div class=\"entry-meta\"><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">(Sófocles e outros.) <strong>Quão grande</strong> (Aristófanes, Platão e outros; SIG 850, 11; PTebt 27, 78 [123 a.C.]; Josefo, Bell. 1, 626; Ant. 8, 208). <span class=\"greek\">ἡλίκον</span> <span class=\"greek\">ἀγῶνα</span> <span class=\"greek\">ἔχω</span>, «quão grande luta tenho», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.2.1\" target=\"_blank\" rel=\"noopener noreferrer\">Cl 2:1</a>. <span class=\"greek\">ἡλίκην</span> <span class=\"greek\">ἔχει</span> <span class=\"greek\">βάσανον</span>, «quão grande tormento alguma coisa causa», 2Cl 10:4. <span class=\"greek\">ἡλίκοις</span> <span class=\"greek\">γράμμασιν</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.6.11\" target=\"_blank\" rel=\"noopener noreferrer\">Gl 6:11</a>, variante de leitura: aqui <span class=\"greek\">ἡλ</span>. também pode significar «quão pequeno» (Antífanes, Com. 166, 6; Luciano, Herm. 5; Epicteto 1, 12, 26). Em jogo de palavras, <span class=\"greek\">ἰδοὺ</span> <span class=\"greek\">ἡλίκον</span> <span class=\"greek\">πῦρ</span> <span class=\"greek\">ἡλίκην</span> <span class=\"greek\">ὕλην</span> <span class=\"greek\">ἀνάπτει</span>, «vede quão grande bosque uma pequena chama incendeia», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.3.5\" target=\"_blank\" rel=\"noopener noreferrer\">Tg 3:5</a>. — DELG; M-M.</p></section></article>\n<article id=\"entry-elios-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἥλιος, ου, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">(Homero e autores posteriores; empréstimo ao vocabulário rabínico.) <strong>Sol</strong>, com ou sem artigo (B-D-F §253, 1; PBerl 11710, 4, com artigo [Otero, p. 84, n.º 4]; plural em TestAbr A 7, p. 84, 4 [Stone, p. 16]), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.13.43\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 13:43</a>; 17:2 (cf. OdeSol 11:13); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.21.25\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 21:25</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.2.20\" target=\"_blank\" rel=\"noopener noreferrer\">At 2:20</a> (Jl 3:4); 26:13; 27:20; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.15.41\" target=\"_blank\" rel=\"noopener noreferrer\">1Co 15:41</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.1.16\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 1:16</a>; 6:12; 8:12; 10:1; 12:1 (cf. Atena associada ao sol, <em>Ptocheia ou Odisseu disfarçado em Troia</em>, PKöln VI, 245 [= ASP 31], 1991, 41–44; Ísis igualmente nos versos 13–16; IMaronIsis 9, [<span class=\"greek\">ὅτ</span>]<span class=\"greek\">αν</span> <span class=\"greek\">οἷ</span> <span class=\"greek\">ἔβλεψα</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">ἥλιον</span>, «sempre que, com que [olhos] eu vi o sol»); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.16.8\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 16:8</a>; 19:17; 21:23; 22:5; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.1.32\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 1:32</a> e outras passagens. — DELG; M-M; TW. </p></section><p class=\"entry-text\">Continuação integral dos testemunhos da fonte: Ap 16:8; 19:17; 21:23; 1Cl 20:3; B 5:10; 15:5; Dg 7:2; IEph 19:2; Hm 12, 4, 1 (acréscimo do códice A); Hs 9, 2, 2; 9, 17, 4; 9, 21, 1, 3. <span class=\"greek\">ἥλ</span>., «calor do sol» (Polieno 8, 10, 3; Is 49:10; Jn 4:8b), Ap 7:16; ou «luz solar», At 13:11 (Diodoro Sículo 10, 20, 3, <span class=\"greek\">ἐφορᾶν</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">ἥλιον</span>; 18, 27, 2; Máximo de Tiro 27, 3d, <span class=\"greek\">ἥλιος</span> em lugar de <span class=\"greek\">ἐξ</span> <span class=\"greek\">ἡλίου</span> <span class=\"greek\">αὐγή</span>; Sl 57:9; Josefo, Ant. 16, 204, <span class=\"greek\">τ</span>. <span class=\"greek\">ἥλιον</span> <span class=\"greek\">βλέπ</span>.; Atanásio 17, 2, <span class=\"greek\">ἐν</span> <span class=\"greek\">ἡλίῳ</span>). Com verbos: <span class=\"greek\">ἀνατέλλειν</span> (ver <span class=\"greek\">ἀνατέλλω</span> 1 e 2), «nascer», Mt 5:45; 13:6; Mc 4:6; 16:2; Tg 1:11; <span class=\"greek\">λάμπειν</span>, «brilhar», GPt 6:22; <span class=\"greek\">ἐκλάμπειν</span>, «resplandecer», Hv 4, 1, 6; <span class=\"greek\">ἐπικαίειν</span>, «queimar», Hs 9, 1, 6; <span class=\"greek\">δύνειν</span> (ver verbete), «pôr-se», Mc 1:32; Lc 4:40; GPt 2:5; 5:15; <span class=\"greek\">ἐπιδύειν</span>, «pôr-se», Ef 4:26; <span class=\"greek\">σκοτίζεσθαι</span>, «escurecer», Mt 24:29; Mc 13:24; Lc 23:45, variante de leitura; <span class=\"greek\">σκοτοῦσθαι</span>, Ap 9:2; <span class=\"greek\">ἐκλείπειν</span>, «eclipsar-se» (Pseudo-Luciano, Philopatris 24), Lc 23:45. <span class=\"greek\">ἀνατολὴ</span> <span class=\"greek\">ἡλίου</span>, «oriente, nascente do sol» (ver <span class=\"greek\">ἀνατολή</span> 2a), Ap 7:2; 16:12; <span class=\"greek\">φῶς</span> <span class=\"greek\">ἡλίου</span>, «luz do sol» (Licurgo, Fgm. 77; Élio Aristides 45, 29 K.; Justino, D. 128, 24), Ap 22:5; <span class=\"greek\">πρὸ</span> <span class=\"greek\">ἡλίου</span> <span class=\"greek\">κ</span>. <span class=\"greek\">σελήνης</span>, «antes da criação do sol e da lua», 2Cl 14:1. <span class=\"greek\">ὁ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">ἡλίου</span> <span class=\"greek\">βωμός</span>, «o altar do sol ou de Hélio», 1Cl 25:4 (<span class=\"greek\">ἥλ</span>. como divindade: Díon Crisóstomo 3, 73; Máximo de Tiro 19, 3d [Pitágoras]; Josefo, C. Ap. 2, 265; Ar. 6, 1ss.; Atanásio 28, 4). — F. Boll, *D. Sonne im Glauben u. in d. Weltanschauung d. alten Völker*, 1922; K. Schauenburg, *Helios*, 1955; G. Halsberghe, *The Cult of Sol Invictus*, 1972; B. 54; DELG; LfgrE 894 (bibliografia); DDD, s.v. Helios; M-M; TW.</p></article>\n<article id=\"entry-elioupolis-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Ἡλιούπολις, εως, ἡ</h1><div class=\"entry-meta\"><span>nome próprio feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">(Ver <span class=\"greek\">ἥλιος</span>, <span class=\"greek\">πόλις</span>; Sócrates, Ep. 26, 1 [<span class=\"greek\">Ἡλίου</span> <span class=\"greek\">πόλις</span>]; Arriano, Anab. 3, 1, 3 [<span class=\"greek\">Ἡλιούπολις</span>]; Êx 1:11 [<span class=\"greek\">Ἡλίου</span> <span class=\"greek\">πόλις</span>]; TestJos 18:3; JosAs; Demétrio: 722 Fgm. 1:12 Jac.; Fílon, Somn. 1, 77; Josefo, C. Ap. 1, 250, 261, 265; Atanásio 28, 1.) <strong>Heliópolis</strong>, cidade do Baixo Egito com templo do deus-sol; figura na lenda da ave fênix, 1Cl 25:3.</p></section></article>\n<article id=\"entry-elos-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἧλος, ου, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">(Homero e outros; inscrições, papiros, LXX; Josefo, Ant. 5, 208; Justino, Melitão; sobre crucificação, Asclepíades Júnior [médico, séculos I/II d.C.], em Alexandre de Trales 1, 15.) <strong>Prego, cravo</strong>, GPt 6:21; MPol 13:3. <span class=\"greek\">ὁ</span> <span class=\"greek\">τύπος</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">ἥλων</span>, «a marca dos cravos», Jo 20:25ab; também <span class=\"greek\">ὁ</span> <span class=\"greek\">τόπος</span> <span class=\"greek\">τ</span>. <span class=\"greek\">ἥλων</span>, «o lugar dos cravos», versículo 25b. — J. Hewitt, HTR 25, 1932, 29–45; B. 597; DELG; M-M.</p></section></article>\n<article id=\"entry-elysion-pedion-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Ἠλύσιον πεδίον, τό</h1><div class=\"entry-meta\"><span>expressão nominal neutra</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">(Sobre a etimologia, ver DELG e Frisk; desde Homero, Odisseia 4, 563; também SibOr 2, 338.) <strong>Campo Elísio, Campos Elísios, Elísio</strong>, chamados também «Ilhas dos Bem-aventurados», ApcPtRainer 2, 1. — J. Kroll, <em>Elysium</em>, 1953. Ver <span class=\"greek\">Ἀχερούσιος</span>.</p></section></article>\n<article id=\"entry-emeis-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἡμεῖς</h1><div class=\"entry-meta\"><span>pronome pessoal remissivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">Ver <span class=\"greek\">ἐγώ</span>.</p></section></article>\n<article id=\"entry-emera-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἡμέρα, ας, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">(Homero e autores posteriores; empréstimo no vocabulário rabínico.)</p><p class=\"entry-text\">① <strong>Período entre o nascer e o pôr do sol: dia.</strong></p><p class=\"entry-text\">ⓐ Em sentido literal, oposto a <span class=\"greek\">νύξ</span>, «noite» (Atanásio 24, 2, <span class=\"greek\">ἀντιδοξοῦντι</span> … <span class=\"greek\">ὡς</span> … <span class=\"greek\">τῇ</span> <span class=\"greek\">ἡμέρᾳ</span> <span class=\"greek\">νύξ</span>), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.4.2\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 4:2</a> (jejum de quarenta dias e noites, como em Êx 34:28; ver <span class=\"greek\">νύξ</span> 1d; cf. JosAs 13:8, <span class=\"greek\">ἑπτὰ</span> <span class=\"greek\">ἡμέρας</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ἑπτὰ</span> <span class=\"greek\">νύκτας</span>; Luciano, Ver. Hist. 1, 10, <span class=\"greek\">ἑπτὰ</span> <span class=\"greek\">ἡμέρας</span> <span class=\"greek\">κ</span>. <span class=\"greek\">τὰς</span> <span class=\"greek\">ἴσας</span> <span class=\"greek\">νύκτας</span>); 12:40 e frequentemente. <span class=\"greek\">ἡμέρα</span> <span class=\"greek\">γίνεται</span>, «amanhece» (Xenofonte, An. 2, 2, 13; 7, 2, 34; Apiano, Iber. 74 §315; Josefo, Ant. 10, 202; Vi. 405), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.4.42\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 4:42</a>; 6:13; 22:66; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.12.18\" target=\"_blank\" rel=\"noopener noreferrer\">At 12:18</a>; 16:35; 27:29, 39. <span class=\"greek\">ἡμέρα</span> <span class=\"greek\">διαυγάζει</span>, «o dia desponta», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2PE.1.19\" target=\"_blank\" rel=\"noopener noreferrer\">2Pe 1:19</a>; <span class=\"greek\">κλίνει</span>, «declina, aproxima-se a tarde», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.9.12\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 9:12</a>; 24:29 (cf. Justino, D. 56, 16, <span class=\"greek\">ἡμέρα</span> <span class=\"greek\">προκόπτει</span>); <span class=\"greek\">φαίνει</span>, «brilha», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.8.12\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 8:12</a>. Genitivo temporal <span class=\"greek\">ἡμέρας</span>, «à luz do dia» (Hipócrates, Ep. 19, 7; Arriano, Ind. 13, 6; Luciano, Ver. Hist. 1, 10), 1Cl 25:4; <span class=\"greek\">ἡμέρας</span> <span class=\"greek\">μέσης</span>, «ao meio-dia» (Luciano, Nigr. 34; cf. Josefo, Ant. 5, 190), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.26.13\" target=\"_blank\" rel=\"noopener noreferrer\">At 26:13</a>; ou período em que ocorre algo, <span class=\"greek\">ἡμέρας</span>, «durante o dia», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.21.25\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 21:25</a>. <span class=\"greek\">ἡμέρας</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">νυκτός</span>, «de dia e de noite» (Apiano, Liby. 121 §576; Arriano, Anab. 7, 11, 4; Josefo, Ant. 11, 171; Justino, D. 1, 4, <span class=\"greek\">δι</span>’ <span class=\"greek\">ὅλης</span> <span class=\"greek\">νυκτὸς</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ἡμέρας</span>; também ordem inversa, Is 34:10), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.5.5\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 5:5</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.18.7\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 18:7</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.9.24\" target=\"_blank\" rel=\"noopener noreferrer\">At 9:24</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.2.9\" target=\"_blank\" rel=\"noopener noreferrer\">1Ts 2:9</a>; 3:10; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TH.3.8\" target=\"_blank\" rel=\"noopener noreferrer\">2Ts 3:8</a>; AcPl Ha 2, 10; 3, 2. Acusativo temporal <span class=\"greek\">νύκτα</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ἡμέραν</span>, «durante a noite e o dia» (Díon Crisóstomo 7 [8], 15; Élio Aristides 51, 1 K. = 27, p. 534 D.; Est 4:16; cf. <span class=\"greek\">νύκτωρ</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">μεθ</span>’ <span class=\"greek\">ἡμέραν</span>, Melitão, HE 4, 26, 5; Atanásio 34, 3), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.4.27\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 4:27</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.2.37\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 2:37</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.20.31\" target=\"_blank\" rel=\"noopener noreferrer\">At 20:31</a>; 26:7. <span class=\"greek\">τὰς</span> <span class=\"greek\">ἡμέρας</span>, «todos os dias», oposto a <span class=\"greek\">τὰς</span> <span class=\"greek\">νύκτας</span> (Díon Crisóstomo 4, 36; Josefo, C. Ap. 1, 199), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.21.37\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 21:37</a>; cf. <span class=\"greek\">πᾶσαν</span> <span class=\"greek\">ἡμέραν</span>, «todos os dias» (Heródoto 7, 203, 1), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.5.42\" target=\"_blank\" rel=\"noopener noreferrer\">At 5:42</a>. <span class=\"greek\">τὴν</span> <span class=\"greek\">ἡμέραν</span> <span class=\"greek\">ἐκείνην</span>, «durante aquele dia» (Élio Aristides 49, 45 K.), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.1.39\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 1:39</a>; <span class=\"greek\">ὅλην</span> <span class=\"greek\">τ</span>. <span class=\"greek\">ἡμ</span>., «durante todo o dia» (Josefo, Ant. 6, 22), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.20.6\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 20:6</a>. Acusativo distributivo: <span class=\"greek\">συμφωνεῖν</span> <span class=\"greek\">ἐκ</span> <span class=\"greek\">δηναρίου</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">ἡμέραν</span>, «acordar um denário por dia», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.20.2\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 20:2</a> (Meisterhans³-Schw. 205; papiros em Mlt., ClR 15, 1901, 436; 18, 1904, 152). <span class=\"greek\">ἡμέρας</span> <span class=\"greek\">ὁδός</span>, «caminhada de um dia», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.2.44\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 2:44</a> (Xenofonte, An. 2, 2, 12; Gn 31:23; 1Mc 5:24; Josefo, C. Ap. 2, 21, 23). A luz do dia dura doze horas, período em que se pode caminhar sem tropeçar, Jo 11:9ab. <span class=\"greek\">ἡ</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">ἡμέρᾳ</span> <span class=\"greek\">τρυφή</span>, «devassidão em pleno dia», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2PE.2.13\" target=\"_blank\" rel=\"noopener noreferrer\">2Pe 2:13</a>.</p><p class=\"entry-text\">ⓑ Figuradamente (SibOr 5, 241), os cristãos são <span class=\"greek\">υἱοὶ</span> <span class=\"greek\">φωτὸς</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">υἱοὶ</span> <span class=\"greek\">ἡμέρας</span>, «filhos da luz e filhos do dia», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.5.5\" target=\"_blank\" rel=\"noopener noreferrer\">1Ts 5:5</a>; cf. versículo 8 (em contraste, Aristófanes, Fgm. 573 K., chama depreciativamente Quérefonte, amigo de Sócrates, <span class=\"greek\">νυκτὸς</span> <span class=\"greek\">παῖδα</span>, «filho da noite»). Em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.9.4\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 9:4</a>, o dia representa o período da vida humana; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.13.12\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 13:12s</a>.</p><p class=\"entry-text\">② <strong>Dia civil ou jurídico, incluindo a noite: dia</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.6.34\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 6:34</a>; 15:32; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.6.21\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 6:21</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.13.14\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 13:14</a>; B 15:3ss.; em contraste com horas, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.25.13\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 25:13</a>; com horas, meses e anos, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.9.15\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 9:15</a>; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.4.10\" target=\"_blank\" rel=\"noopener noreferrer\">Gl 4:10</a>.</p><p class=\"entry-text\">ⓐ Genitivo respondendo à pergunta «por quanto tempo?» (Nicóstrato, Com. Fgm. 5 K., <span class=\"greek\">ἡμερῶν</span> <span class=\"greek\">τριῶν</span> <span class=\"greek\">ἤδη</span>, «já há três dias»; Porfírio, Vi. Plotini 13 W., <span class=\"greek\">τριῶν</span> <span class=\"greek\">ἡμ</span>.; BGU 37, 7 [50 d.C.]; 249, 11 [70–80 d.C.], <span class=\"greek\">ἡμερῶν</span> <span class=\"greek\">δύο</span> <span class=\"greek\">διαμένομεν</span>): <span class=\"greek\">τεσσεράκοντα</span> <span class=\"greek\">ἡμερῶν</span>, «durante quarenta dias», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.1.3\" target=\"_blank\" rel=\"noopener noreferrer\">At 1:3</a>, códice D*. <span class=\"greek\">ἑκάστης</span> <span class=\"greek\">ἡμέρας</span>, «a cada dia», AcPl Ha 6, 8 (ILegGort 1, 9, multa <span class=\"greek\">τᾶς</span> <span class=\"greek\">ἁμέρας</span> <span class=\"greek\">ϝεκάστας</span>, «por cada dia»; sobre o genitivo, Buck, Dialects §170; Justino, D. 2, 6 e outros). Dativo respondendo «quando?» (Xenofonte, An. 4, 7, 8; Jt 7:6; Est 7:2; Bel 40, Teodocião; JosAs 11:1; Justino, A I, 67, 7): <span class=\"greek\">τῇ</span> <span class=\"greek\">τρίτῃ</span> <span class=\"greek\">ἡμέρᾳ</span>, «no terceiro dia» (Arriano, Anab. 6, 4, 1, <span class=\"greek\">τρίτῃ</span> <span class=\"greek\">ἡμ</span>.; AscIs 3:16; JosAs 29:8; Justino, D. 100, 1 e outros; cf. D. 85, 6, <span class=\"greek\">τῇ</span> <span class=\"greek\">δευτέρᾳ</span> <span class=\"greek\">ἡμ</span>.), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.16.21\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 16:21</a>; 17:23; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.9.22\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 9:22</a>; 24:7, 46; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.15.4\" target=\"_blank\" rel=\"noopener noreferrer\">1Co 15:4</a>. <span class=\"greek\">ᾗ</span> <span class=\"greek\">δὲ</span> <span class=\"greek\">ἡμέρᾳ</span>, «no dia em que» (PLille 15, 1 [242 a.C.], <span class=\"greek\">ᾗ</span> <span class=\"greek\">ἡμέρᾳ</span>; 1Esd 1:49; Josefo, Ant. 20, 26), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.17.29\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 17:29</a>; cf. versículo 30. <span class=\"greek\">μιᾷ</span> <span class=\"greek\">ἡμέρᾳ</span>, «num só dia» (Apiano, Iber. 58 §244), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.10.8\" target=\"_blank\" rel=\"noopener noreferrer\">1Co 10:8</a>.</p><p class=\"entry-text\">ⓑ Acusativo respondendo habitualmente «por quanto tempo?» (Xenofonte, An. 4, 7, 18; Nicolau de Damasco 90 Fgm. 130, 26, p. 410, 30 Jac., <span class=\"greek\">τὴν</span> <span class=\"greek\">ἡμέραν</span> <span class=\"greek\">ἐκείνην</span>, «durante aquele dia»; Polieno 6, 53, <span class=\"greek\">τρεῖς</span> <span class=\"greek\">ἡμέρας</span>; Arriano, Anab. 6, 2, 3; Luciano, Alex. 15, <span class=\"greek\">ἡμέρας</span>, «vários dias»; Fílon, Vi. Cont. 30, <span class=\"greek\">τὰς</span> <span class=\"greek\">ἓξ</span> <span class=\"greek\">ἡμέρας</span>; JosAs 10:20, <span class=\"greek\">τὰς</span> <span class=\"greek\">ἑπτὰ</span> <span class=\"greek\">ἡμέρας</span>): <span class=\"greek\">ὅλην</span> <span class=\"greek\">τ</span>. <span class=\"greek\">ἡμέραν</span>, «durante o dia todo», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.8.36\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 8:36</a> (Sl 43:23); 10:21 (Is 65:2); <span class=\"greek\">ἡμέραν</span> <span class=\"greek\">μίαν</span>, «por um dia», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.21.7\" target=\"_blank\" rel=\"noopener noreferrer\">At 21:7</a> (Justino, D. 12, 3). <span class=\"greek\">ἔμειναν</span> <span class=\"greek\">οὐ</span> <span class=\"greek\">πολλὰς</span> <span class=\"greek\">ἡμέρας</span>, «permaneceram não muitos dias», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.2.12\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 2:12</a>; cf. 4:40; 11:6; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.9.19\" target=\"_blank\" rel=\"noopener noreferrer\">At 9:19</a>; 10:48; 16:12; 20:6c; 21:4, 10; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.1.18\" target=\"_blank\" rel=\"noopener noreferrer\">Gl 1:18</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.11.3\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 11:3</a>, 9. <span class=\"greek\">ἡμέραν</span> <span class=\"greek\">ἐξ</span> <span class=\"greek\">ἡμέρας</span>, «dia após dia» (Pseudo-Eurípides, Rhes. 445s.; Henioco 5, 13 Kock; Gn 39:10; Nm 30:15; Is 58:2; Sl 95:2; Eclo 5:7; En), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2PE.2.8\" target=\"_blank\" rel=\"noopener noreferrer\">2Pe 2:8</a>; 2Cl 11:2 (citação de origem desconhecida; ver final da acepção ②ⓔ). Raramente o acusativo responde «quando?» (Antífanes Com. [século IV a.C.], Fgm. 280; Pseudo-Luciano, Halc. 3, <span class=\"greek\">τρίτην</span> <span class=\"greek\">ἡμ</span>.): <span class=\"greek\">τὴν</span> <span class=\"greek\">ἡμέραν</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">πεντηκοστῆς</span>, «no dia de Pentecostes», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.20.16\" target=\"_blank\" rel=\"noopener noreferrer\">At 20:16</a>. Expressão peculiar <span class=\"greek\">τεσσαρεσκαιδεκάτην</span> <span class=\"greek\">σήμερον</span> <span class=\"greek\">ἡμέραν</span> <span class=\"greek\">προσδοκῶντες</span>, «este é o décimo quarto dia em que esperais», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.27.33\" target=\"_blank\" rel=\"noopener noreferrer\">At 27:33</a> (Xenofonte, An. 4, 5, 24, <span class=\"greek\">ἐνάτην</span> <span class=\"greek\">ἡμέραν</span> <span class=\"greek\">γεγαμημένην</span>). <span class=\"greek\">ἑπτάκις</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">ἡμέρας</span>, «sete vezes ao dia», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.17.4\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 17:4</a>.</p><p class=\"entry-text\">ⓒ Com preposições: <span class=\"greek\">ἀπό</span> + genitivo, «desde», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.22.46\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 22:46</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.11.53\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 11:53</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.20.18\" target=\"_blank\" rel=\"noopener noreferrer\">At 20:18</a>. <span class=\"greek\">ἀφ</span>’ <span class=\"greek\">ἧς</span> <span class=\"greek\">ἡμέρας</span> (PRev 9, 1 [258 a.C.]; PsSol 18:11s.; EpArist 24), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.1.6\" target=\"_blank\" rel=\"noopener noreferrer\">Cl 1:6</a>, 9; Hm 4, 4, 3. <span class=\"greek\">ἀπὸ</span> … <span class=\"greek\">ἄχρι</span> …, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.1.5\" target=\"_blank\" rel=\"noopener noreferrer\">Fp 1:5</a>; <span class=\"greek\">ἀπὸ</span> … <span class=\"greek\">μέχρι</span> …, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.10.30\" target=\"_blank\" rel=\"noopener noreferrer\">At 10:30</a>. <span class=\"greek\">ἄχρι</span> + genitivo, «até», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.24.38\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 24:38b</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.20\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 1:20</a>; 17:27; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.1.2\" target=\"_blank\" rel=\"noopener noreferrer\">At 1:2</a>; 2:29; <span class=\"greek\">ἄχρι</span> <span class=\"greek\">ἡμερῶν</span> <span class=\"greek\">πέντε</span>, «cinco dias depois», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.20.6\" target=\"_blank\" rel=\"noopener noreferrer\">At 20:6b</a>. <span class=\"greek\">μέχρι</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">σήμερον</span> (<span class=\"greek\">ἡμέρας</span>), «até o dia presente» (1Esd 8:74), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.28.15\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 28:15</a>; <span class=\"greek\">ἕως</span> <span class=\"greek\">τ</span>. <span class=\"greek\">ἡμέρας</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.27.64\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 27:64</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.1.22\" target=\"_blank\" rel=\"noopener noreferrer\">At 1:22</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.11.8\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 11:8</a> (Dt 29:3; Justino, D. 134, 5, <span class=\"greek\">ἕως</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">σήμερον</span> <span class=\"greek\">ἡμ</span>.; Atanásio 2, 1, <span class=\"greek\">εἰς</span> … <span class=\"greek\">τὴν</span> <span class=\"greek\">σήμερον</span> <span class=\"greek\">ἡμ</span>.). <span class=\"greek\">δι</span>’ <span class=\"greek\">ἡμερῶν</span>, «após [alguns] dias», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.2.1\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 2:1</a> (Heródoto 6, 118, 3, <span class=\"greek\">δι</span>’ <span class=\"greek\">ἐτέων</span> <span class=\"greek\">εἴκοσι</span>; Tucídides 2, 94, 3; Platão, Hipp. Maj. 281a, <span class=\"greek\">διὰ</span> <span class=\"greek\">χρόνου</span>, «após [longo] tempo»); <span class=\"greek\">διὰ</span> <span class=\"greek\">τριῶν</span> <span class=\"greek\">ἡμερῶν</span>, «dentro de três dias» (PPetr II, 4 [6], 8, <span class=\"greek\">δι</span>’ <span class=\"greek\">ἡμερῶν</span> <span class=\"greek\">ε</span>´, «ao longo de cinco dias»), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.26.61\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 26:61</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.14.58\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 14:58</a>; <span class=\"greek\">δι</span>’ <span class=\"greek\">ἡμερῶν</span> <span class=\"greek\">τεσσεράκοντα</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.1.3\" target=\"_blank\" rel=\"noopener noreferrer\">At 1:3</a> (ver <span class=\"greek\">διά</span> A 2a). <span class=\"greek\">διὰ</span> <span class=\"greek\">τ</span>. <span class=\"greek\">ἡμέρας</span>, «durante o dia», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.9.37\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 9:37</a>, códice D; <span class=\"greek\">εἰς</span> <span class=\"greek\">τ</span>. <span class=\"greek\">ἡμέραν</span>, «para o dia» (PPetr III, 95, coluna 2, 6 [século III a.C.]), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.12.7\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 12:7</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.9.15\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 9:15</a>; <span class=\"greek\">εἰς</span> <span class=\"greek\">ἡμέρας</span> <span class=\"greek\">μ</span>´, «por quarenta dias», AcPl Ha 6, 11. <span class=\"greek\">ἐν</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">ἡμ</span>., «de dia», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.11.9\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 11:9b</a>; <span class=\"greek\">ἐν</span> <span class=\"greek\">μιᾷ</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">ἡμερῶν</span>, «certo dia», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.5.17\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 5:17</a>; 8:22; 20:1; <span class=\"greek\">ἐν</span> com dativo singular, «em, no», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.24.50\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 24:50</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.59\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 1:59</a>; 13:31, variante; Justino, D. 29, 3, <span class=\"greek\">ἐν</span> <span class=\"greek\">ταύτῃ</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">ἡμ</span>.; 111, 3, <span class=\"greek\">ἐν</span> <span class=\"greek\">ἡμ</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">πάσχα</span>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.5.9\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 5:9</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.4.4\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 4:4</a> (Gn 2:2); AcPl Ha 3, 9. Com dativo plural, «dentro de», «no decorrer de» (Alexis Com. 246, 2 K., <span class=\"greek\">ἐν</span> <span class=\"greek\">πένθ</span>’ <span class=\"greek\">ἡμέραις</span>; Fílon, Somn. 2, 112; TestJob 30:4; JosAs 21:7, <span class=\"greek\">ἐν</span> <span class=\"greek\">ταῖς</span> <span class=\"greek\">ἑπτὰ</span> <span class=\"greek\">ἡμέραις</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">γάμου</span>): <span class=\"greek\">ἐν</span> <span class=\"greek\">τρισὶν</span> <span class=\"greek\">ἡμέραις</span> (PTebt 14, 5 [114 a.C.]; Porfírio, Vi. Plot. 17, p. 111, 26 W.; TestJob 24:9; EpArist 24), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.27.40\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 27:40</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.15.29\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 15:29</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.2.19\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 2:19s</a>. <span class=\"greek\">ἐπί</span> + acusativo, «durante»: <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">ἡμέρας</span> <span class=\"greek\">πλείους</span>, «por muitos dias» (PTurin I, 2, 15 [116 a.C.], <span class=\"greek\">ἐφ</span>’ <span class=\"greek\">ἱκανὰς</span> <span class=\"greek\">ἡμ</span>.; Josefo, Ant. 4, 277), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.13.31\" target=\"_blank\" rel=\"noopener noreferrer\">At 13:31</a>; cf. 27:20; <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">πολλὰς</span> <span class=\"greek\">ἡμ</span>. (Josefo, Ant. 18, 57), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.16.18\" target=\"_blank\" rel=\"noopener noreferrer\">At 16:18</a>; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.11.30\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 11:30</a>. <span class=\"greek\">καθ</span>’ <span class=\"greek\">ἡμέραν</span>, «todos os dias» (Hipérides 6, 23, 26; Políbio 1, 57, 7; 4, 18, 2; Diodoro Sículo 1, 36, 7–8; 2, 47, 2; SIG 656, 22; UPZ 42, 13 [162 a.C.]; PGiss 17, 1; Tb 10:7; Sus 8, 12, Teodocião; 1Mc 8:15; EpArist 304; Josefo, Bell. 2, 265; Ant. 20, 205; Ar. [POxy 1778, 27]; Justino, D. 39, 2), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.26.55\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 26:55</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.14.49\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 14:49</a> («durante o dia»: A. Argyle, ET 63, 1951/52, 354); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.16.19\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 16:19</a>; 22:53; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.2.46\" target=\"_blank\" rel=\"noopener noreferrer\">At 2:46s</a>.; 3:2; 16:5; 17:11; 19:9; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.15.31\" target=\"_blank\" rel=\"noopener noreferrer\">1Co 15:31</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.11.28\" target=\"_blank\" rel=\"noopener noreferrer\">2Co 11:28</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.7.27\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 7:27</a>; 10:11. Também, com artigo facultativo (B-D-F §160; Rob. 766), <span class=\"greek\">τὸ</span> <span class=\"greek\">καθ</span>’ <span class=\"greek\">ἡμ</span>. (Aristófanes, Equ. 1126; Platão; Políbio 4, 18, 2; POxy 1220, 4; TestJob 14:2; mas <span class=\"greek\">καθ</span>’ <span class=\"greek\">ἡμ</span>. em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.2.45\" target=\"_blank\" rel=\"noopener noreferrer\">At 2:45</a>, códice D), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.11.3\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 11:3</a>; 19:47; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.17.11\" target=\"_blank\" rel=\"noopener noreferrer\">At 17:11</a>, variante. <span class=\"greek\">καθ</span>’ <span class=\"greek\">ἑκάστην</span> <span class=\"greek\">ἡμ</span>., «todos os dias» (Xenofonte, Mem. 4, 2, 12; Equ. 5, 9; PTebt 412, 2; Mitt-Wilck. I/2, 327, 18; Êx 5:8; Est 2:11; Jó 1:4; Bel 4:6; PsSol 18:11; GrBar 8:4), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.3.13\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 3:13</a>. <span class=\"greek\">κατὰ</span> <span class=\"greek\">πᾶσαν</span> <span class=\"greek\">ἡμ</span>. com o mesmo sentido (Josefo, Ant. 6, 49), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.17.17\" target=\"_blank\" rel=\"noopener noreferrer\">At 17:17</a>. <span class=\"greek\">μεθ</span>’ <span class=\"greek\">ἡμέρας</span> <span class=\"greek\">ἕξ</span>, «seis dias depois» (PSI 502, 16 [257 a.C.], <span class=\"greek\">μεθ</span>’ <span class=\"greek\">ἡμέρας</span> <span class=\"greek\">ιβ</span>´; PSI 436, 3; Justino, D. 27, 5, <span class=\"greek\">μετὰ</span> <span class=\"greek\">μίαν</span> <span class=\"greek\">ἡμ</span>.), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.17.1\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 17:1</a>; cf. 26:2; 27:63; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.8.31\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 8:31</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.24\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 1:24</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.4.43\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 4:43</a>; 20:26; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.1.5\" target=\"_blank\" rel=\"noopener noreferrer\">At 1:5</a>; 15:36; 24:1; 28:13; AcPl Ha 1, 33; 11, 8; AcPlCor 2:30. <span class=\"greek\">πρὸ</span> <span class=\"greek\">ἓξ</span> <span class=\"greek\">ἡμερῶν</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">πάσχα</span>, «seis dias antes da Páscoa», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.12.1\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 12:1</a> (não é latinismo, pois consta em Hipócrates, <span class=\"greek\">πρὸ</span> <span class=\"greek\">τριῶν</span> <span class=\"greek\">ἡμερῶν</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">τελευτῆς</span> [W. Schulze, Graeca Latina, 1901, 15; Rydbeck 64s.]; cf. Plutarco, Symp. 8, 717d; Luciano, De Morte Peregr. 1; Eliano, HA 11, 19; inscrição dos mistérios de Andânia [SIG 736, 70, <span class=\"greek\">πρὸ</span> <span class=\"greek\">ἁμερᾶν</span> <span class=\"greek\">δέκα</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">μυστηρίων</span>]; PFay 118, 15; PHolm 4, 23; PGM 13, 26, 671; Am 1:1; 2Mc 15:36; Josefo, Ant. 15, 408; Justino, D. 27, 5; W. Schmid, <em>D. Attizismus</em> III, 1893, 287s.; IV, 1897, 629; Mlt. 100s.; B-D-F §213). Notável o nominativo indicando tempo em <span class=\"greek\">ἤδη</span> <span class=\"greek\">ἡμέραι</span> <span class=\"greek\">τρεῖς</span> <span class=\"greek\">προσμένουσίν</span> <span class=\"greek\">μοι</span>, «já há três dias permanecem comigo», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.15.32\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 15:32</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.8.2\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 8:2</a>; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.9.28\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 9:28</a> (B-D-F §144; Rob. 460).</p><p class=\"entry-text\">ⓓ Sobre dias festivos: <span class=\"greek\">ἡ</span> <span class=\"greek\">ἡμέρα</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">σαββάτων</span> (ver <span class=\"greek\">σάββατον</span> 1b<span class=\"greek\">β</span>), ou <span class=\"greek\">τοῦ</span> <span class=\"greek\">σαββάτου</span> (<span class=\"greek\">σάββατον</span> 1a), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.4.16\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 4:16</a>; 13:14b, 16; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.19.31\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 19:31</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.13.14\" target=\"_blank\" rel=\"noopener noreferrer\">At 13:14</a> (Justino, D. 27, 5). <span class=\"greek\">ἡ</span> <span class=\"greek\">ἡμέρα</span> ou <span class=\"greek\">αἱ</span> <span class=\"greek\">ἡμέραι</span> <span class=\"greek\">τ</span>. <span class=\"greek\">ἀζύμων</span>, «dia(s) dos pães ázimos», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.22.7\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 22:7</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.12.3\" target=\"_blank\" rel=\"noopener noreferrer\">At 12:3</a>; 20:6. <span class=\"greek\">ἡ</span> <span class=\"greek\">ἡμέρα</span> <span class=\"greek\">τ</span>. <span class=\"greek\">πεντηκοστῆς</span>, «dia de Pentecostes», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.2.1\" target=\"_blank\" rel=\"noopener noreferrer\">At 2:1</a>; 20:16. <span class=\"greek\">μεγάλη</span> <span class=\"greek\">ἡμέρα</span>, «o grande dia [da expiação]», PtK 2, p. 14, 29. De festa judaica em geral, GJs 1:2; 2:2 (o autor já não compreende claramente qual festa é designada; ver Amann e de Strycker em 1:2). <span class=\"greek\">ἡ</span> <span class=\"greek\">κυριακὴ</span> <span class=\"greek\">ἡμέρα</span>, «dia do Senhor, domingo», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.1.10\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 1:10</a> (Justino, A I, 67, 7, <span class=\"greek\">τὴν</span> … <span class=\"greek\">τοῦ</span> <span class=\"greek\">ἡλίου</span> <span class=\"greek\">ἡμέραν</span>). A respeito de observância de festas: <span class=\"greek\">ὸ</span>̔<span class=\"greek\">ς</span> <span class=\"greek\">μὲν</span> <span class=\"greek\">κρίνει</span> <span class=\"greek\">ἡμέραν</span> <span class=\"greek\">παρ</span>’ <span class=\"greek\">ἡμέραν</span>, <span class=\"greek\">ὸ</span>̔<span class=\"greek\">ς</span> <span class=\"greek\">δὲ</span> <span class=\"greek\">κρίνει</span> <span class=\"greek\">πᾶσαν</span> <span class=\"greek\">ἡμέραν</span>, «um considera um dia superior a outro; outro considera bons todos os dias», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.14.5\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 14:5</a>; <span class=\"greek\">φρονεῖν</span> <span class=\"greek\">τ</span>. <span class=\"greek\">ἡμέραν</span>, «observar o dia», versículo 6; <span class=\"greek\">ἡμέρας</span> <span class=\"greek\">παρατηρεῖσθαι</span>, «observar dias», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.4.10\" target=\"_blank\" rel=\"noopener noreferrer\">Gl 4:10</a>. Com genitivo indicando o que ocorre ou deve ocorrer no dia: <span class=\"greek\">ἡμ</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">ἁγνισμοῦ</span>, «dia da purificação», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.21.26\" target=\"_blank\" rel=\"noopener noreferrer\">At 21:26</a>; <span class=\"greek\">τ</span>. <span class=\"greek\">ἐνταφιασμοῦ</span>, «do sepultamento», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.12.7\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 12:7</a>; <span class=\"greek\">ἕως</span> <span class=\"greek\">ἡμέρας</span> <span class=\"greek\">ἀναδείξεως</span> <span class=\"greek\">αὐτοῦ</span> <span class=\"greek\">πρὸς</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">Ἰσραήλ</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.80\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 1:80</a> (ver <span class=\"greek\">ἀνάδειξις</span>).</p><p class=\"entry-text\">ⓔ Terminologia veterotestamentária: «completarem-se os dias» (Êx 7:25; 1Cr 17:11; Tb 10:1b; cf. hebraico מָלֵא): <span class=\"greek\">ἐπλήσθησαν</span> <span class=\"greek\">αἱ</span> <span class=\"greek\">ἡμ</span>. <span class=\"greek\">τῆς</span> <span class=\"greek\">λειτουργίας</span> <span class=\"greek\">αὐτοῦ</span>, «terminaram os dias de seu serviço», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.23\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 1:23</a>; <span class=\"greek\">ἐπλήσθησαν</span> <span class=\"greek\">ἡμ</span>. <span class=\"greek\">ὀκτὼ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">περιτεμεῖν</span> <span class=\"greek\">αὐτόν</span>, «chegou o oitavo dia para circuncidá-lo», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.2.21\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 2:21</a>; cf. versículo 22; ver <span class=\"greek\">ἐκπλήρωσις</span>, <span class=\"greek\">συμπληρόω</span>, <span class=\"greek\">συντελέω</span>, <span class=\"greek\">τελέω</span>, <span class=\"greek\">τελειόω</span>. O hebraico forneceu também <span class=\"greek\">ἡμέρᾳ</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ἡμέρᾳ</span>, «dia após dia» (Est 3:4, יוֹם וָיוֹם = LXX <span class=\"greek\">καθ</span>’ <span class=\"greek\">ἑκάστην</span> <span class=\"greek\">ἡμέραν</span>; יוֹם יוֹם, Sl 68:20 = LXX 67:20, <span class=\"greek\">ἡμέραν</span> <span class=\"greek\">καθ</span>’ <span class=\"greek\">ἡμέραν</span>), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.4.16\" target=\"_blank\" rel=\"noopener noreferrer\">2Co 4:16</a>; GJs 6:1; <span class=\"greek\">ἡμέραν</span> <span class=\"greek\">ἐξ</span> <span class=\"greek\">ἡμέρας</span>, «dia após dia» (frequente no AT para diversas expressões hebraicas, mas também Henioco Com. 5, 13 K.), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2PE.2.8\" target=\"_blank\" rel=\"noopener noreferrer\">2Pe 2:8</a>; citação profética de origem desconhecida, 2Cl 11:2; <span class=\"greek\">ἡμέρᾳ</span> <span class=\"greek\">ἀφ</span>’ <span class=\"greek\">ἡμέρας</span>, GJs 12:3.</p><p class=\"entry-text\">③ <strong>Dia designado para finalidade especial; data marcada</strong> (UPZ 66, 5 [153 a.C.], <span class=\"greek\">ἡ</span> <span class=\"greek\">ἡμ</span>., «dia do casamento»; inscrição ÖJh 64, 1995, p. 74, sobre comemoração do fundador de Éfeso, <span class=\"greek\">τῇ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">Ἀνδρόκλου</span> <span class=\"greek\">ἡμέρᾳ</span>); por exemplo, o parto, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.16.21\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 16:21</a>, variante de leitura.</p><p class=\"entry-text\">ⓐ <span class=\"greek\">τακτῇ</span> <span class=\"greek\">ἡμέρᾳ</span>, «no dia determinado», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.12.21\" target=\"_blank\" rel=\"noopener noreferrer\">At 12:21</a>; <span class=\"greek\">ἡμέραν</span> <span class=\"greek\">τάξασθαι</span>, «marcar um dia» (Políbio 18, 19, 1), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.28.23\" target=\"_blank\" rel=\"noopener noreferrer\">At 28:23</a>; <span class=\"greek\">στῆσαι</span>, «estabelecer [um dia]» (Dionísio de Halicarnasso 6, 48), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.17.31\" target=\"_blank\" rel=\"noopener noreferrer\">At 17:31</a>; <span class=\"greek\">ὁρίζειν</span>, «determinar [um dia]» (Políbio, Dionísio de Halicarnasso; Epicteto, Ench. 51, 1), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.4.7\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 4:7</a>; Hv 2, 2, 5. Do dia do recenseamento (ver <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.2.1\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 2:1</a>), <span class=\"greek\">αὕτη</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">ἡμέρα</span> <span class=\"greek\">κυρίου</span>, «este é o dia do Senhor», GJs 17:1; <span class=\"greek\">ἐν</span> <span class=\"greek\">ἡμέρᾳ</span>, <span class=\"greek\">ᾗ</span> <span class=\"greek\">ἔμελλεν</span> <span class=\"greek\">θηριομαχῖν</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">Παῦλος</span>, «no dia em que Paulo devia enfrentar as feras», AcPl Ha 3, 9.</p><p class=\"entry-text\">ⓑ Especialmente <strong>dia do julgamento</strong>, fixado por um juiz.</p><p class=\"entry-text\"><span class=\"greek\">α</span>. <span class=\"greek\">ἀνθρωπίνη</span> <span class=\"greek\">ἡμ</span>., «dia de um tribunal humano», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.4.3\" target=\"_blank\" rel=\"noopener noreferrer\">1Co 4:3</a> (inscrição em amuleto monetiforme [séculos II/III d.C.], em que C. Bonner, HTR 43, 1950, 165–68, traduz por «julgamento humano»). Essa expressão se baseia no uso de <span class=\"greek\">ἡμ</span>. para designar a data judicial.</p><p class=\"entry-text\"><span class=\"greek\">β</span>. <strong>Dia do julgamento final de Deus</strong> (ver <span class=\"greek\">ὥρα</span> 3): <span class=\"greek\">ᾗ</span> <span class=\"greek\">ἡμ</span>. <span class=\"greek\">ὁ</span> <span class=\"greek\">υἱὸς</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">ἀνθρώπου</span> <span class=\"greek\">ἀποκαλύπτεται</span>, «no dia em que o Filho do Homem se revela», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.17.30\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 17:30</a>; <span class=\"greek\">ἡ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span> <span class=\"greek\">ἡμ</span>., «dia de Deus», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2PE.3.12\" target=\"_blank\" rel=\"noopener noreferrer\">2Pe 3:12</a>; <span class=\"greek\">ἡ</span> <span class=\"greek\">ἡμέρα</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">μεγάλη</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span> <span class=\"greek\">τ</span>. <span class=\"greek\">παντοκράτορος</span>, «grande dia do Deus Todo-Poderoso», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.16.14\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 16:14</a>. <span class=\"greek\">ἡμ</span>. <span class=\"greek\">κυρίου</span>, «dia do Senhor» (Jl 1:15; 2:1, 11; Is 13:6, 9 e outros): uma única ocorrência no NT para o dia de Deus, o Senhor, numa citação do AT, <span class=\"greek\">πρὶν</span> <span class=\"greek\">ἐλθεῖν</span> <span class=\"greek\">ἡμ</span>. <span class=\"greek\">κυρίου</span> <span class=\"greek\">τ</span>. <span class=\"greek\">μεγάλην</span> <span class=\"greek\">κ</span>. <span class=\"greek\">ἐπιφανῆ</span>, «antes de vir o grande e manifesto dia do Senhor», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.2.20\" target=\"_blank\" rel=\"noopener noreferrer\">At 2:20</a> (Jl 3:4; cf. JosAs 14:2). Nas demais ocorrências, Jesus Cristo é o Senhor desse dia: <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.5.5\" target=\"_blank\" rel=\"noopener noreferrer\">1Co 5:5</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.5.2\" target=\"_blank\" rel=\"noopener noreferrer\">1Ts 5:2</a> (P.-É. Langevin, <em>Jesus Seigneur</em>, 1967, 107–67; G. Holland, SBLSP 24, 1985, 327–41); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TH.2.2\" target=\"_blank\" rel=\"noopener noreferrer\">2Ts 2:2</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2PE.3.10\" target=\"_blank\" rel=\"noopener noreferrer\">2Pe 3:10</a>. Frequentemente é nomeado ou identificado como <span class=\"greek\">υἱὸς</span> <span class=\"greek\">τ</span>. <span class=\"greek\">ἀνθρώπου</span>, «Filho do Homem», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.17.24\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 17:24</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.1.8\" target=\"_blank\" rel=\"noopener noreferrer\">1Co 1:8</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.1.14\" target=\"_blank\" rel=\"noopener noreferrer\">2Co 1:14</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.1.6\" target=\"_blank\" rel=\"noopener noreferrer\">Fp 1:6</a>, 10; 2:16. <span class=\"greek\">ἡ</span> <span class=\"greek\">ἐσχάτη</span> <span class=\"greek\">ἡμ</span>., «último dia [desta era]» (ver <span class=\"greek\">ἔσχατος</span> 2b), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.6.39\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 6:39s</a>., 44, 54; 11:24; 12:48; Hv 2, 2, 5. <span class=\"greek\">ἡμ</span>. (<span class=\"greek\">τῆς</span>) <span class=\"greek\">κρίσεως</span>, «dia do julgamento» (Pv 6:34; Jt 16:17; PsSol 15:12; En; GrBar 1:7; cf. TestLevi 3:2, 3; Justino, D. 38, 2; Taciano 12, 4), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.10.15\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 10:15</a>; 11:22, 24; 12:36; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2PE.2.9\" target=\"_blank\" rel=\"noopener noreferrer\">2Pe 2:9</a>; 3:7; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1JN.4.17\" target=\"_blank\" rel=\"noopener noreferrer\">1Jo 4:17</a>; 2Cl 17:6; B 19:10. <span class=\"greek\">ἐν</span> <span class=\"greek\">ἡμέρᾳ</span> <span class=\"greek\">ὄτε</span> <span class=\"greek\">κρίνει</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">θεὸς</span> <span class=\"greek\">διὰ</span> <span class=\"greek\">Χρ</span>. <span class=\"greek\">Ἰ</span>., «no dia em que Deus julgará por meio de Cristo Jesus», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.2.16\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 2:16</a> (R. Bultmann, TLZ 72, 1947, 200s., considera isso glosa). <span class=\"greek\">ἡμ</span>. <span class=\"greek\">ὀργῆς</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ἀποκαλύψεως</span> <span class=\"greek\">δικαιοκρισίας</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span>, «dia da ira e da revelação do justo julgamento de Deus», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.2.5\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 2:5</a> (cf. Sf 1:15, 18; 2:3; Ez 7:19, variante; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.6.17\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 6:17</a>). <span class=\"greek\">ἡ</span> <span class=\"greek\">ἡμ</span>. <span class=\"greek\">ἡ</span> <span class=\"greek\">μεγάλη</span>, «o grande dia» (Jr 37:7; Ml 3:22), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.6.17\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 6:17</a>; 16:14; <span class=\"greek\">ἡμ</span>. <span class=\"greek\">μεγάλη</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">θαυμαστή</span>, «grande e admirável dia», B 6:4; <span class=\"greek\">ἡμ</span>. <span class=\"greek\">ἀπολυτρώσεως</span>, «dia da redenção», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.4.30\" target=\"_blank\" rel=\"noopener noreferrer\">Ef 4:30</a>; <span class=\"greek\">ἡμ</span>. <span class=\"greek\">ἐπισκοπῆς</span>, «dia da visitação» (ver <span class=\"greek\">ἐπισκοπή</span> 1a,b), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.2.12\" target=\"_blank\" rel=\"noopener noreferrer\">1Pe 2:12</a>; <span class=\"greek\">ἡμ</span>. <span class=\"greek\">ἀνταποδόσεως</span>, «dia da recompensa», B 14:9 (Is 61:2). <span class=\"greek\">ἐκείνη</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">ἡμ</span>., «aquele dia» (Sf 1:15; Am 9:11; Zc 12:3s.; Is 10:20; Jr 37:7s.), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.7.22\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 7:22</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.6.23\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 6:23</a>; 10:12; 21:34; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TH.1.10\" target=\"_blank\" rel=\"noopener noreferrer\">2Ts 1:10</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.1.12\" target=\"_blank\" rel=\"noopener noreferrer\">2Tm 1:12</a>, 18; 4:8; AcPlCor 2:32. Talvez <span class=\"greek\">ἡμ</span>. <span class=\"greek\">σφαγῆς</span>, «dia de matança» (Jr 12:3; En 16:1), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.5.5\" target=\"_blank\" rel=\"noopener noreferrer\">Tg 5:5</a>, pertença aqui (ver <span class=\"greek\">σφαγή</span>). Em uso absoluto, <span class=\"greek\">ἡμ</span>., <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.3.13\" target=\"_blank\" rel=\"noopener noreferrer\">1Co 3:13</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.10.25\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 10:25</a>; B 7:9; 21:3; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.5.4\" target=\"_blank\" rel=\"noopener noreferrer\">1Ts 5:4</a>. <span class=\"greek\">ἡμέρα</span> <span class=\"greek\">αἰῶνος</span>, «dia da eternidade» (Eclo 18:10), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2PE.3.18\" target=\"_blank\" rel=\"noopener noreferrer\">2Pe 3:18</a>, também tem conotação escatológica: o dia em que começa a eternidade ou o dia que constitui a própria eternidade; neste último sentido, caberia na acepção seguinte.</p><p class=\"entry-text\">④ <strong>Período prolongado: tempo, época</strong> (como hebraico יוֹם, mas conhecido também entre gregos: Sófocles, Aj. 131, 623; Eurípides, Ion 720; Aristóteles, Rhet. 2, 13, 1389b, 33s.; PAmh 30, 43 [século II a.C.], <span class=\"greek\">ἡμέρας</span> <span class=\"greek\">αἰτοῦσα</span>, «pediu tempo, uma trégua»).</p><p class=\"entry-text\">ⓐ Singular: <span class=\"greek\">ἐν</span> <span class=\"greek\">τ</span>. <span class=\"greek\">ἡμέρᾳ</span> <span class=\"greek\">τ</span>. <span class=\"greek\">πονηρᾷ</span>, «quando os tempos são maus» (a não ser que se refira ao julgamento final), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.6.13\" target=\"_blank\" rel=\"noopener noreferrer\">Ef 6:13</a>; <span class=\"greek\">ἐν</span> <span class=\"greek\">ἡμ</span>. <span class=\"greek\">σωτηρίας</span>, «na época de salvação» que chegou aos cristãos, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.6.2\" target=\"_blank\" rel=\"noopener noreferrer\">2Co 6:2</a> (Is 49:8). Da época da libertação do Egito: <span class=\"greek\">ἐν</span> <span class=\"greek\">ἡμέρᾳ</span> <span class=\"greek\">ἐπιλαβομένου</span> <span class=\"greek\">μου</span> <span class=\"greek\">τ</span>. <span class=\"greek\">χειρὸς</span> <span class=\"greek\">αὐτῶν</span>, «no tempo em que os tomei pela mão», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.8.9\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 8:9</a> (Jr 38:32; sobre a construção, cf. Br 2:28; B-D-F §423, 5; Rob. 514). <span class=\"greek\">ἐν</span> <span class=\"greek\">ἐκείνῃ</span> <span class=\"greek\">τ</span>. <span class=\"greek\">ἡμέρᾳ</span>, «naquele tempo», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.2.20\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 2:20b</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.14.20\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 14:20</a>; 16:23, 26; <span class=\"greek\">τ</span>. <span class=\"greek\">ἡμέραν</span> <span class=\"greek\">τ</span>. <span class=\"greek\">ἐμήν</span>, «meu tempo, minha época», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.8.56\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 8:56</a>; <span class=\"greek\">ἐν</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">ἐσχάτῃ</span> <span class=\"greek\">αὐτοῦ</span> <span class=\"greek\">ἡμέρᾳ</span>, «nos últimos dias dele [Abraão]», GJs 1:3.</p><p class=\"entry-text\">ⓑ Sobretudo no plural, <span class=\"greek\">αἱ</span> <span class=\"greek\">ἡμέραι</span>, «dias, épocas» da vida ou atividade de alguém, com genitivo pessoal (1Km 17:12, códice A; 2Km 21:1; 3Km 10:21; Est 1:1s.; Eclo 46:7; 47:1; <span class=\"greek\">ἡμέραι</span> <span class=\"greek\">αὐτοῦ</span>, En 12:2; <span class=\"greek\">ἡμέραι</span> <span class=\"greek\">ἃς</span> <span class=\"greek\">ἦτε</span>, En 102:5): <span class=\"greek\">ἐν</span> <span class=\"greek\">ἡμέραις</span> <span class=\"greek\">Ἡρῴδου</span>, «nos dias de Herodes», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.2.1\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 2:1</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.5\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 1:5</a>; <span class=\"greek\">Νῶε</span>, «de Noé», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.17.26\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 17:26a</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.3.20\" target=\"_blank\" rel=\"noopener noreferrer\">1Pe 3:20</a>; <span class=\"greek\">Ἠλίου</span>, «de Elias», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.4.25\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 4:25</a>; <span class=\"greek\">ἐν</span> <span class=\"greek\">ταῖς</span> <span class=\"greek\">ἡμ</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">υἱοῦ</span> <span class=\"greek\">τ</span>. <span class=\"greek\">ἀνθρώπου</span>, «nos dias do Filho do Homem», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.17.26\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 17:26b</a>; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.23.30\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 23:30</a>; <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">τ</span>. <span class=\"greek\">ἡμερῶν</span> <span class=\"greek\">Ἰωάννου</span>, «desde os dias de João», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.11.12\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 11:12</a>; <span class=\"greek\">ἕως</span> <span class=\"greek\">τ</span>. <span class=\"greek\">ἡμερῶν</span> <span class=\"greek\">Δαυίδ</span>, «até os dias de Davi», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.7.45\" target=\"_blank\" rel=\"noopener noreferrer\">At 7:45</a>; cf. 13:41 (Hc 1:5). Com genitivo de coisa, <span class=\"greek\">ἡμέραι</span> <span class=\"greek\">ἐκδικήσεως</span>, «tempo de vingança», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.21.22\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 21:22</a>; <span class=\"greek\">τ</span>. <span class=\"greek\">ἀπογραφῆς</span>, «do recenseamento», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.5.37\" target=\"_blank\" rel=\"noopener noreferrer\">At 5:37</a>; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.10.7\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 10:7</a>; 11:6; <span class=\"greek\">ἐν</span> <span class=\"greek\">τ</span>. <span class=\"greek\">ἡμέραις</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">σαρκὸς</span> <span class=\"greek\">αὐτοῦ</span>, «no tempo da sua manifestação na carne», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.5.7\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 5:7</a>. <span class=\"greek\">ἡμέραι</span> <span class=\"greek\">πονηραί</span>, «tempos maus», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.5.16\" target=\"_blank\" rel=\"noopener noreferrer\">Ef 5:16</a>; cf. B 2:1; 8:6; <span class=\"greek\">ἡμ</span>. <span class=\"greek\">ἀγαθαί</span>, «tempos felizes» (Artemidoro 4, 8), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.3.10\" target=\"_blank\" rel=\"noopener noreferrer\">1Pe 3:10</a> (Sl 33:13); <span class=\"greek\">ἀφ</span>’ <span class=\"greek\">ἡμερῶν</span> <span class=\"greek\">ἀρχαίων</span>, «desde tempos antigos», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.15.7\" target=\"_blank\" rel=\"noopener noreferrer\">At 15:7</a>; <span class=\"greek\">αἱ</span> <span class=\"greek\">πρότερον</span> <span class=\"greek\">ἡμ</span>., «os dias anteriores», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.10.32\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 10:32</a>; <span class=\"greek\">πάσας</span> <span class=\"greek\">τὰς</span> <span class=\"greek\">ἡμέρας</span>, «todo o tempo, sempre», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.28.20\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 28:20</a> (Dt 4:40; 5:29; PsSol 14:4); <span class=\"greek\">νῦν</span> <span class=\"greek\">τ</span>. <span class=\"greek\">ἡμέραις</span>, «nos tempos atuais», Hs 9, 20, 4. <span class=\"greek\">ἐν</span> (<span class=\"greek\">ταῖς</span>) <span class=\"greek\">ἐσχάταις</span> <span class=\"greek\">ἡμ</span>., «nos últimos dias», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.2.17\" target=\"_blank\" rel=\"noopener noreferrer\">At 2:17</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.3.1\" target=\"_blank\" rel=\"noopener noreferrer\">2Tm 3:1</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.5.3\" target=\"_blank\" rel=\"noopener noreferrer\">Tg 5:3</a>; B 4:9; D 16:3; <span class=\"greek\">ἐπ</span>’ <span class=\"greek\">ἐσχάτου</span> <span class=\"greek\">τ</span>. <span class=\"greek\">ἡμερῶν</span> <span class=\"greek\">τούτων</span>, «no fim destes dias», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.1.2\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 1:2</a>; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2PE.3.3\" target=\"_blank\" rel=\"noopener noreferrer\">2Pe 3:3</a>; GJs 7:2. <span class=\"greek\">ἐν</span> <span class=\"greek\">τ</span>. <span class=\"greek\">ἡμέραις</span> <span class=\"greek\">ἐκείναις</span>, «naqueles dias», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.3.1\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 3:1</a>; 24:19, 38; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.1.9\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 1:9</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.2.1\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 2:1</a>; 4:2b; 5:35b; <span class=\"greek\">ἐν</span> <span class=\"greek\">τ</span>. <span class=\"greek\">ἡμ</span>. <span class=\"greek\">ταύταις</span>, «nesses dias», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.39\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 1:39</a>; 6:12; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.1.15\" target=\"_blank\" rel=\"noopener noreferrer\">At 1:15</a>; <span class=\"greek\">εἰς</span> <span class=\"greek\">ταύτας</span> <span class=\"greek\">τ</span>. <span class=\"greek\">ἡμέρας</span>, «no que respeita aos nossos dias» (oposto a <span class=\"greek\">πάλαι</span>), Hs 9, 26, 6; <span class=\"greek\">πρὸ</span> <span class=\"greek\">τούτων</span> <span class=\"greek\">τ</span>. <span class=\"greek\">ἡμερῶν</span>, «antes destes tempos», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.5.36\" target=\"_blank\" rel=\"noopener noreferrer\">At 5:36</a>; 21:38; <span class=\"greek\">πρὸς</span> <span class=\"greek\">ὀλίγας</span> <span class=\"greek\">ἡμ</span>., «por pouco tempo», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.12.10\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 12:10</a>. <span class=\"greek\">ἐλεύσονται</span> <span class=\"greek\">ἡμ</span>., «virão dias»: seguido de <span class=\"greek\">ὅταν</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.9.15\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 9:15</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.2.20\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 2:20a</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.5.35\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 5:35a</a>; de <span class=\"greek\">ὅτε</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.17.22\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 17:22</a> (Justino, D. 40, 2). <span class=\"greek\">ἥξουσιν</span> <span class=\"greek\">ἡμέραι</span> <span class=\"greek\">ἐπί</span> <span class=\"greek\">σε</span> <span class=\"greek\">καί</span>, «virá sobre ti um tempo em que», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.19.43\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 19:43</a>; <span class=\"greek\">ἡμ</span>. <span class=\"greek\">ἔρχονται</span> <span class=\"greek\">καί</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.8.8\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 8:8</a> (Jr 38:31); <span class=\"greek\">ἐλεύσονται</span> <span class=\"greek\">ἡμ</span>. <span class=\"greek\">ἐν</span> <span class=\"greek\">αἷς</span>, «virão dias nos quais», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.21.6\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 21:6</a>; 23:29. Especialmente sobre duração da vida: <span class=\"greek\">πάσαις</span> <span class=\"greek\">τ</span>. <span class=\"greek\">ἡμέραις</span> <span class=\"greek\">ἡμῶν</span>, «durante toda a nossa vida», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.75\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 1:75</a>; <span class=\"greek\">πάσας</span> <span class=\"greek\">τὰς</span> <span class=\"greek\">ἡμέρας</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">ζωῆς</span> <span class=\"greek\">αὐτοῦ</span>, «todos os dias de sua vida», GJs 4:1 (En 103:5; TestJob 46:9); <span class=\"greek\">μήτε</span> <span class=\"greek\">ἀρχὴν</span> <span class=\"greek\">ἡμερῶν</span> <span class=\"greek\">μήτε</span> <span class=\"greek\">ζωῆς</span> <span class=\"greek\">τέλος</span> <span class=\"greek\">ἔχων</span>, «sem princípio de dias nem fim de vida», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.7.3\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 7:3</a>; <span class=\"greek\">προβεβηκὼς</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">ταῖς</span> <span class=\"greek\">ἡμ</span>., «avançado em anos», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.7\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 1:7</a>, 18; cf. 2:36 (Gn 18:11; 24:1; Js 13:1; 23:1; 3Km 1:1; ver <span class=\"greek\">προβαίνω</span> 2). — B. 991; DELG, s.v. <span class=\"greek\">ἦμαρ</span>; EDNT; M-M; TW; Sv.</p></section><p class=\"entry-text\">A fonte conserva ainda estas formas abreviadas nas construções examinadas: <span class=\"greek\">τῇ</span> <span class=\"greek\">τρίτῃ</span> <span class=\"greek\">ἡμ</span>., «no terceiro dia»; <span class=\"greek\">σάββ</span>., abreviação remissiva a <span class=\"greek\">σάββατον</span>, no contexto do dia sabático; <span class=\"greek\">ἡμ</span>. <span class=\"greek\">ὀργῆς</span>, «dia da ira». A expressão <span class=\"greek\">τῇ</span> <span class=\"greek\">ἡμ</span>. conserva o dativo temporal, «no dia». Essas formas remetem às subdivisões ②ⓐ, ②ⓓ e ③ⓑ<span class=\"greek\">β</span>, respectivamente.</p></article>\n<article id=\"entry-emeros-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἥμερος, ον</h1><div class=\"entry-meta\"><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">(Ver o verbete seguinte; significação variando de «domesticado, manso», sobre animais, a «civilizado, gentil», sobre pessoas: Homero e outros; LXX; TestAbr A 2, p. 79, 5 [Stone, p. 6]; EpArist; Fílon; Josefo, C. Ap. 2, 137, 212; empréstimo ao vocabulário rabínico.) <strong>Gentil, bondoso</strong>.</p><p class=\"entry-text\">ⓐ De pessoas que, pela sua conduta, não intimidam outras (Píndaro e outros; SIG 932, 7; OGI 116, 7; Fílon, Leg. ad Gai. 243; Mos. 2, 279; Atanásio 1, 2; R. 49, 8): <strong>gentil, de temperamento brando</strong>, em contraste com <span class=\"greek\">ἄγριος</span>, «selvagem» (cf. Díon Crisóstomo 11 [12], 28), IEph 10:2.</p><p class=\"entry-text\">ⓑ De palavras, <strong>bondosas</strong>, opostas a <span class=\"greek\">ἔκφρικτος</span>, «aterradoras», Hv 1, 3, 3. Comparativo <span class=\"greek\">ἡμερώτερος</span> (desde Ésquilo, Ag. 1632), sobre mandamentos, Hm 12, 4, 5. — DELG; TW.</p></section></article>\n<article id=\"entry-emeroo-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἡμερόω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">(Ver o verbete anterior; Ésquilo, Heródoto e outros; PPrinc 119, 12 [século IV d.C.], sobre terra desbravada para cultivo; Sb 16:18; TestJud 2:3; Fílon.) <strong>Amansar, domesticar</strong>, em sentido figurado a respeito dos maus desejos, Hm 12, 1, 2. — DELG, s.v. <span class=\"greek\">ἥμερος</span>.</p></section></article>\n"};
